{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Lamivudine, a polar cytidine nucleoside analog, has a mean absolute oral bioavailability of 86–88% in HIV patients, demonstrating that small polar nucleosides can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Emtricitabine, a fluorinated cytidine analog, has 93% oral bioavailability unaffected by food, supporting high F for polar nucleoside scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Zalcitabine, a small dideoxycytidine nucleoside, showed 88% oral bioavailability in a patient, providing direct evidence that low-molecular-weight polar nucleosides can exceed the 20% threshold substantially.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Cladribine, a 2-chloro-2'-deoxyadenosine analog, had 48% ± 8% oral bioavailability, well above the 20% threshold, supporting high F for nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Cladribine tablets had an estimated oral bioavailability of 45.6% in a phase III population PK analysis, again supporting high F for nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Didanosine showed a median F of 0.19 under fed conditions, below the 20% threshold, but this is attributed to acid lability and food effects that are not applicable to the carbocyclic guanine query scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple close nucleoside analogs with very high assay-transfer scores show absolute oral bioavailability mostly between 45% and 93%, far above the 20% threshold. The only sub-20% observation (didanosine under fed conditions) is explained by acid lability and food effects, which do not apply to the carbocyclic guanine query. Therefore high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "Didanosine's low F is confounded by acid lability and food effects, limiting its applicability to the carbocyclic guanine scaffold.",
    "Transporter-mediated absorption or efflux for the specific carbocyclic guanine analog is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

